def fill_between(row, acc, new):
    """Recolor every cell strictly between the first and last acc cell of the row with new."""
    js=[j for j,v in enumerate(row) if v==acc]
    if len(js)>=2:
        for j in range(js[0]+1, js[-1]):
            if row[j]!=acc: row[j]=new
    return row

